-- DD S1: the Director Dashboard (S0 report 2026-10-15, every recommended
-- answer accepted as the owner's ruling). Eight tables: the five departments,
-- who directs or views each, the KPI registry (73 rows, EN and ES titles, the
-- open question per row), one snapshot table every source writes, effective
-- dated targets with phasing, the seventeen debates with their rulings, and
-- the typed monthly values (state retail figures, licence counts). Values
-- live in data with code fallbacks: src/directorregistry.ts is the fallback
-- registry and the source the dd_kpis and dd_kpi_questions seed below is
-- generated from (ddSeedSql()); a test compares this file to that output.
-- INSERT OR IGNORE keeps a later value. Ids are TEXT, instants ISO TEXT,
-- flags INTEGER, numbers REAL, lists comma separated TEXT.

CREATE TABLE dd_departments (
  dept_key TEXT PRIMARY KEY,
  sort INTEGER NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

INSERT OR IGNORE INTO dd_departments (dept_key, sort, active, created_at, updated_at) VALUES
  ('bizops', 10, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('farmops', 20, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('culttech', 30, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('sales', 40, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('finance', 50, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z');

-- Who directs or views a department. People are picked in the app; no seed.
CREATE TABLE dd_department_people (
  id TEXT PRIMARY KEY,
  dept_key TEXT NOT NULL REFERENCES dd_departments(dept_key),
  person_id TEXT NOT NULL REFERENCES people(id),
  role TEXT NOT NULL CHECK (role IN ('director', 'viewer')),
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT,
  deleted_at TEXT,
  deleted_by TEXT
);

CREATE INDEX dd_department_people_dept ON dd_department_people (dept_key, deleted_at);

-- The KPI registry. wall_keys lists the walls a tile shows on (the harvest
-- family shows on bizops and farmops). A companion row renders inside its
-- headline tile (companion_of). config_key names the app_config key that
-- holds the ruling behind the row's open question. compute_key is free text
-- in S1: the function or SQL the snapshot engine reuses, as the S0 report
-- names it. goal_direction says which side of the goal reads on goal: at
-- least the goal, or at most it (turnaround days, close days late, all in
-- cost per pound). status: live (the snapshot can run or the hand row can be
-- typed), needs_definition (a ruling is needed first), parked (no build yet).
CREATE TABLE dd_kpis (
  kpi_key TEXT PRIMARY KEY,
  dept_key TEXT NOT NULL REFERENCES dd_departments(dept_key),
  wall_keys TEXT NOT NULL,
  title_en TEXT NOT NULL,
  title_es TEXT NOT NULL,
  unit TEXT NOT NULL CHECK (unit IN ('lb448', 'g', 'ea', 'L', 'usd', 'pct', 'count', 'h', 'days', 'score', 'ratio', 'text', 'mol_m2_day')),
  cadence TEXT NOT NULL CHECK (cadence IN ('daily', 'weekly', 'monthly', 'quarterly', 'seasonal')),
  season_start_md TEXT,
  season_end_md TEXT,
  dims TEXT NOT NULL DEFAULT '',
  goal_kind TEXT NOT NULL CHECK (goal_kind IN ('none', 'app_config', 'field_estimates', 'gc_budget_lines', 'gc_drivers', 'gc_submission', 'targets', 'manual')),
  goal_ref TEXT,
  goal_direction TEXT NOT NULL DEFAULT 'at_least' CHECK (goal_direction IN ('at_least', 'at_most')),
  compute_key TEXT,
  source_kind TEXT NOT NULL CHECK (source_kind IN ('app', 'hand', 'connector', 'mount', 'gc', 'mixed')),
  stale_after_hours INTEGER,
  status TEXT NOT NULL CHECK (status IN ('live', 'needs_definition', 'parked')),
  def_version INTEGER NOT NULL DEFAULT 1,
  open_question_en TEXT,
  open_question_es TEXT,
  config_key TEXT,
  companion_of TEXT,
  workbook_rows TEXT,
  sort INTEGER NOT NULL,
  active INTEGER NOT NULL DEFAULT 1,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE INDEX dd_kpis_dept_sort ON dd_kpis (dept_key, active, sort);

-- One snapshot row per KPI, period, dimension and source. A restated value
-- supersedes the live row (superseded_at) and keeps the history. A hand row
-- carries the person and the reason that typed it.
CREATE TABLE dd_kpi_values (
  id TEXT PRIMARY KEY,
  kpi_key TEXT NOT NULL,
  period_kind TEXT NOT NULL CHECK (period_kind IN ('day', 'week', 'month', 'quarter', 'season')),
  period_start TEXT NOT NULL,
  dim_key TEXT NOT NULL DEFAULT '',
  value REAL,
  value_text TEXT,
  goal REAL,
  n INTEGER,
  source TEXT NOT NULL,
  source_as_of TEXT,
  computed_at TEXT NOT NULL,
  def_version INTEGER NOT NULL,
  superseded_at TEXT,
  entered_by TEXT,
  reason TEXT,
  created_at TEXT NOT NULL
);

CREATE UNIQUE INDEX dd_kpi_values_live
  ON dd_kpi_values (kpi_key, period_kind, period_start, dim_key, source)
  WHERE superseded_at IS NULL;

CREATE INDEX dd_kpi_values_key_period ON dd_kpi_values (kpi_key, period_start);

-- Effective dated targets per KPI and dimension. No seed.
CREATE TABLE dd_targets (
  id TEXT PRIMARY KEY,
  kpi_key TEXT NOT NULL,
  dim_key TEXT NOT NULL DEFAULT '',
  period_kind TEXT NOT NULL,
  effective_from TEXT NOT NULL,
  target REAL NOT NULL,
  low REAL,
  high REAL,
  phasing TEXT,
  note TEXT,
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT,
  deleted_at TEXT,
  deleted_by TEXT
);

CREATE UNIQUE INDEX dd_targets_live
  ON dd_targets (kpi_key, dim_key, period_kind, effective_from)
  WHERE deleted_at IS NULL;

-- The share of an annual goal each week or month carries. No seed (G1 waits on the owner).
CREATE TABLE dd_phasing (
  id TEXT PRIMARY KEY,
  scope_key TEXT NOT NULL,
  period_kind TEXT NOT NULL CHECK (period_kind IN ('week', 'month')),
  period_index INTEGER NOT NULL,
  share REAL NOT NULL,
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT
);

CREATE INDEX dd_phasing_scope ON dd_phasing (scope_key, period_kind, period_index);

-- The debates: the owner's question, the two positions, the recommendation
-- and the value the ruling writes to config_key. A ruling in the app bumps
-- the definition version of the rows in kpi_keys and restates open periods.
CREATE TABLE dd_kpi_questions (
  id TEXT PRIMARY KEY,
  question_key TEXT NOT NULL UNIQUE,
  kpi_keys TEXT NOT NULL,
  config_key TEXT,
  question_en TEXT NOT NULL,
  question_es TEXT NOT NULL,
  position_a TEXT NOT NULL,
  position_b TEXT NOT NULL,
  recommendation TEXT NOT NULL,
  default_value TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('open', 'ruled', 'parked')),
  ruling TEXT,
  ruled_by TEXT,
  ruled_at TEXT,
  reason TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

-- Typed values with no table of their own yet (the state's monthly retail
-- figures, the active retail licence count). A later row supersedes. No seed.
CREATE TABLE dd_manual_values (
  id TEXT PRIMARY KEY,
  value_key TEXT NOT NULL,
  period_kind TEXT NOT NULL,
  period_start TEXT NOT NULL,
  value REAL,
  value_text TEXT,
  unit TEXT,
  source TEXT,
  as_of TEXT,
  note TEXT,
  entered_by TEXT,
  reason TEXT,
  created_at TEXT NOT NULL,
  superseded_at TEXT
);

CREATE INDEX dd_manual_values_key_period ON dd_manual_values (value_key, period_start, superseded_at);

-- The registry and the debates, generated by ddSeedSql() in src/directorregistry.ts.

