  ('harvest.wet_weight_lb', 'bizops', 'bizops,farmops', 'Harvest wet weight, day and season to date', 'Peso húmedo de cosecha, día y temporada a la fecha', 'lb448', 'daily', NULL, NULL, 'farm', 'none', NULL, 'at_least', 'loadHarvestConsole dayWet and yearWet SQL (src/console.ts:2850-2869) and consoleBoxes wetDay, wetYear (:1013-1014); the day SQL gains ownLotSql and status <> weighing in S3 and the console''s day pane changes with it; formatLbs at 448', 'app', 30, 'live', 1, 'The day pane carries no toll gate (ownLotSql) while the year pane does; the lot date law for the day figure (debate lot_date_law)', 'El panel del día no tiene filtro de maquila (ownLotSql) y el del año sí; la ley de fecha del lote para la cifra del día (debate lot_date_law)', 'dd_lot_date_law', NULL, '47', 210, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('harvest.pct_complete', 'bizops', 'bizops,farmops', 'Percent finished (plants)', 'Porcentaje terminado (plantas)', 'pct', 'daily', NULL, NULL, 'farm', 'none', NULL, 'at_least', 'consoleBoxes farmTotal, farmHarvestedNow, pct (src/console.ts:990-1005) over the remaining SQL (:2822-2827) and farm_plant_counts (:2944-2946)', 'app', 30, 'live', 1, 'A plant flagged harvested but not yet gone (harvested = 1, gone_at NULL): remaining as the console says, or finished as strain performance says', 'Una planta marcada cosechada pero aún no retirada (harvested = 1, gone_at NULL): restante como dice la consola, o terminada como dice el rendimiento por variedad', 'dd_plants_harvested_flag', NULL, '49', 220, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('harvest.ppp_dry_lb', 'bizops', 'bizops,farmops', 'PPP dry: yesterday, average HTD, projected', 'PPP seco: ayer, promedio HTD, proyectado', 'lb448', 'daily', '09-01', '10-31', 'farm,strain', 'field_estimates', 'estimateInForce', 'at_least', 'consoleBoxes dryPerPlant for HTD by farm (src/console.ts:1006-1012, the dried filter :1010-1012); buildStrainPerformance dryLbPerPlant per strain (src/strainperformance.ts:284-287, :332) once it adopts the same filter; yesterday = lots whose unload day is D-1 (src/drystrain.ts:86-89, 289-292); projected at farm and Total grain only, per dd_projection_basis; the harvest year as /harvest shows it', 'app', 30, 'live', 1, 'Wet, dry or bud (debate ppp_basis); HTD start (debate htd_start); projection basis (debate projected_basis); lot date law', 'Húmedo, seco o flor (debate ppp_basis); inicio de HTD (debate htd_start); base de la proyección (debate projected_basis); ley de fecha del lote', 'dd_ppp_basis', NULL, '50,69', 230, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('harvest.ppp_wet_lb', 'bizops', 'bizops,farmops', 'PPP wet: yesterday, average HTD', 'PPP húmedo: ayer, promedio HTD', 'lb448', 'daily', '09-01', '10-31', 'farm,strain', 'none', NULL, 'at_least', 'consoleBoxes wetPerPlant over every counted lot (src/console.ts:1006-1009); yesterday = lots whose cut day is D-1 under dd_lot_date_law, gated by ownLotSql and status <> weighing; no projected cell', 'app', 30, 'live', 1, 'The lot date law for the yesterday cell (debate lot_date_law); a lot with no plant count is in neither row until the Assign Plant Counts station writes one', 'La ley de fecha del lote para la celda de ayer (debate lot_date_law); un lote sin conteo de plantas no está en ninguna fila hasta que la estación de asignar conteos escribe uno', 'dd_ppp_basis', 'harvest.ppp_dry_lb', '50,69', 240, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('harvest.btr_pct', 'bizops', 'bizops,farmops,culttech', 'BTR: yesterday, weighted average to date, projected', 'BTR: ayer, promedio ponderado a la fecha, proyectado', 'pct', 'daily', '10-01', '12-31', 'shift,farm,strain', 'app_config', 'trim_bogey_pct', 'at_least', 'trimFigures btr per shift (src/console.ts:465-559, :537), trimTotalsLine day weighted BTR (:1324-1328), weightedBtrToDate over TRIM_SEASON_SQL (:1293-1310, :2674-2682), parseBtrTypeCodes (src/config.ts:1641-1644); the console law: WASTE in, no WIP term to date, btr_type_codes folded into the definition version; strain grain from buildStrainPerformance (src/strainperformance.ts:314-315, :333) for the culttech wall; projected = the season weighted rate to date with the trim bogey beside it', 'app', 30, 'live', 1, 'Which BTR formula is canon (debate btr_formula); projected basis; WIP left in the denominator per shift but not to date; WASTE out when strains are compared', 'Qué fórmula de BTR es canon (debate btr_formula); base de la proyección; WIP queda en el denominador por turno pero no a la fecha; WASTE fuera al comparar variedades', 'dd_btr_formula', NULL, '53,25', 250, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
