  ('harvest.wet_lb_per_dlh', 'bizops', 'bizops,farmops', 'Harvest lbs per labor hour vs goal', 'Libras de cosecha por hora de mano de obra vs meta', 'ratio', 'daily', NULL, NULL, '', 'app_config', 'dd_goal_wet_lb_per_dlh', 'at_least', 'consoleBoxes perDlh (src/console.ts:1047-1061): day wet grams over the ALL row else the farm rows of harvest_labor_hours (sheet sync also writes those rows, src/sheetsync.ts:386-430); the Total box only', 'app', 30, 'live', 1, 'The goal lb per DLH for harvest and trim, one number or per farm and shift', 'La meta de libras por hora directa para cosecha y recorte, un solo número o por granja y turno', 'dd_goal_wet_lb_per_dlh', NULL, '48', 270, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z');

