  ('sales.active_accounts_count', 'sales', 'sales', 'Active accounts and reorders', 'Cuentas activas y recompras', 'count', 'monthly', NULL, NULL, '', 'none', NULL, 'at_least', 'one scan over live mounted_sales_orders keyed COALESCE(customer_id, customer_license, customer_name): MIN and MAX order_date, order count; active = an order inside dd_sales_active_days; the reorder rate bounded at 100 percent as the companion view', 'mount', 960, 'live', 1, 'The active window and the customer key (debate active_window)', 'La ventana de actividad y la clave de cliente (debate active_window)', 'dd_sales_active_days', NULL, '7', 360, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z');

