  ('finance.close_days_late', 'finance', 'finance', 'Close on time', 'Cierre a tiempo', 'days', 'monthly', NULL, NULL, '', 'app_config', 'dd_close_target_business_days', 'at_most', 'business days from month end to MIN(gc_upload_log.created_at) for the close (migrations/0103:142-153), or a typed close complete date', 'gc', 960, 'live', 1, 'The close target in business days; upload instant or a typed close date', 'La meta de cierre en días hábiles; instante de carga o fecha de cierre escrita', 'dd_close_target_business_days', NULL, '12,43', 470, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
