  ('finance.all_in_cost_per_dry_lb', 'finance', 'finance', 'All in cost per dry lb', 'Costo total por libra seca', 'usd', 'monthly', NULL, NULL, '', 'gc_budget_lines', 'M.cost', 'at_most', 'M.actual plus the GLs in dd_all_in_addback_gls over own lot weighed dry grams at 448 g (STRAIN_PERFORMANCE_LOTS_SQL with ownLotSql); beside it the GRIPCasting landing scope figure (compute() M.cost over M.vol.adjDry, parity with app.js:853) over the dd_plan_source submission''s snapshot with the current close''s actuals, and a bridge row of the add back dollars', 'mixed', 960, 'live', 1, 'Scope (debate all_in_cost_scope); forecast sellable dry lbs or weighed dry lbs', 'Alcance (debate all_in_cost_scope); libras secas vendibles pronosticadas o libras secas pesadas', 'dd_all_in_addback_gls', NULL, '13', 490, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('finance.all_in_cost_per_bud_lb', 'finance', 'finance', 'All in cost per bud lb', 'Costo total por libra de flor', 'usd', 'monthly', NULL, NULL, '', 'gc_budget_lines', 'M.cost', 'at_most', 'as finance.all_in_cost_per_dry_lb over bud grams from TRIM_SEASON_SQL rows in btr_type_codes; landing scope = compute() M.cost over M.vol.bud', 'mixed', 960, 'live', 1, 'Show both or one; bud forecast or weighed', 'Mostrar ambos o uno; flor pronosticada o pesada', 'dd_all_in_addback_gls', NULL, '44', 500, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('finance.forecast_landing_usd', 'finance', 'finance,bizops', 'Forecasting by BU: budget, actual to date, remaining, landing, variance', 'Pronóstico por unidad de negocio: presupuesto, real a la fecha, restante, aterrizaje, variación', 'usd', 'monthly', NULL, NULL, 'bu', 'gc_budget_lines', 'buTable', 'at_least', 'latest kind bu gc_submissions per bu_code on the current close (migrations/0103:204-224; routes.ts:98-107), or buTable(compute()) live; the final submission''s bu_subs map names the folded BU submissions; the bizops remaining forecast spend tile reads the same rows (remaining, landing, variance in cents, migrations/0103:210-214)', 'gc', 960, 'live', 1, 'The latest submission or the live forecast (edited after submit); remaining = GRIPCasting remaining spend or budget minus actual', 'La última entrega o el pronóstico vivo (editado después de entregar); restante = gasto restante de GRIPCasting o presupuesto menos real', 'dd_plan_source', NULL, '45,64', 510, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
