  ('finance.revenue_vs_plan_usd', 'finance', 'finance', 'Revenue vs plan (monthly)', 'Ingresos vs plan (mensual)', 'usd', 'monthly', NULL, NULL, '', 'gc_submission', 'revenue', 'at_least', 'gc_actual_monthly rows with gl under 5000 for the month on the current close (parseQB keeps any 4 digit account) and revenueActual harvest to date (src/gripcasting/model.ts:204); plan from the dd_plan_source submission, phased by dd_phasing', 'gc', 960, 'live', 1, 'Plan source and phasing (debate plan_source)', 'Fuente del plan y fraseo (debate plan_source)', 'dd_plan_source', NULL, '6', 530, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('finance.state_retail_sales_usd', 'finance', 'finance', 'Monthly retail data report', 'Informe mensual de datos minoristas', 'usd', 'monthly', NULL, NULL, '', 'none', NULL, 'at_least', 'three typed dd_manual_values rows per month: state_retail_sales_usd, state_flower_avg_price_per_lb (typed per ounce, stored per 448 g pound with the conversion shown), mi_retail_licenses_active; the last doubles as the market penetration denominator', 'hand', 960, 'live', 1, 'What the report is and who produces it (debate retail_data_report)', 'Qué es el informe y quién lo produce (debate retail_data_report)', 'dd_retail_report_source', NULL, '38', 540, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z');

