  ('culttech.strain_scorecard', 'culttech', 'culttech', 'Strain scorecard', 'Tarjeta de puntaje por variedad', 'score', 'seasonal', NULL, NULL, 'strain', 'none', NULL, 'at_least', 'derived columns from puzzleNumbers and buildStrainPerformance (BTR, PPP, bag appeal, terps, durability, silo durability, hang dry, cryo durability, finishing window, finish timing), dry down from the strain and farm pools, aW first check from lab_sample_requests kind aw, cryo yield from runs; hand scores in dd_strain_scores (S12)', 'mixed', NULL, 'live', 1, 'The rubric for bag appeal, durability and finish timing; whether the 1 to 6 scale applies only to finish timing; the aW pass threshold', 'La rúbrica de apariencia, durabilidad y momento de terminado; si la escala 1 a 6 aplica solo al momento de terminado; el umbral de aprobación de aW', 'dd_btr_formula', NULL, '82', 710, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
