) VALUES
  ('culttech.contra_recompenses_usd', 'culttech', 'culttech', 'Continuum contra recompenses', 'Contrarrecompensas de Continuum', 'usd', 'weekly', NULL, NULL, '', 'none', NULL, 'at_least', 'none until the owner rules (debate contra_recompenses); the recorded log shape: partner key from the four PARTNERS, signed amount, direction, optional project label, shown gross each way, feeding no finance row', 'hand', NULL, 'parked', 1, 'What the term means and who holds the ledger today', 'Qué significa el término y quién lleva el registro hoy', 'dd_contra_recompenses_mode', NULL, '85', 730, 1, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z');

INSERT OR IGNORE INTO dd_kpi_questions (
  id, question_key, kpi_keys, config_key, question_en, question_es, position_a, position_b, recommendation, default_value, status, ruling, ruled_by, ruled_at, reason, created_at, updated_at
) VALUES
  ('ddq_ppp_basis', 'ppp_basis', 'harvest.ppp_dry_lb,harvest.ppp_wet_lb,harvest.dry_lb_per_plant_vs_plan_pct,culttech.projected_yield_lb,culttech.strain_scorecard', 'dd_ppp_basis', 'On the daily PPP tile, should the bold headline be dry pounds per plant at 448 g (the unloaded silo weight, wet per plant as the second row), or wet with dry second?', 'En la tarjeta diaria de PPP, ¿el titular en negrita debe ser libras secas por planta a 448 g (el peso descargado del silo, con húmedo por planta como segunda fila), o húmedo con seco en segunda fila?', 'Dry pounds per plant at 448 g is the headline: it is the only basis with a yield plan, a projection and parity with the strain pages.', 'Wet pounds per plant is the headline: it exists the day after the cut, covers the same lots in numerator and denominator, and never drops frozen lots.', 'Dry is the headline and wet is the second row on the same tile, each yesterday cell dated on its own day (unload day for dry, cut day for wet), with projected and vs plan in dry only.', 'dry', 'ruled', 'dry', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_htd_start', 'htd_start', 'sales.returns_count,harvest.ppp_dry_lb,harvest.ppp_wet_lb', 'dd_sales_htd_start_mmdd', 'Do you accept that average HTD PPP and projected PPP count the lots of the farm today''s minted harvest year exactly as /harvest does, while returns HTD on the sales list counts from April 1 beside revenue vs plan, each tile printing its start and end?', '¿Acepta que el PPP promedio HTD y el PPP proyectado cuenten los lotes del año de cosecha acuñado del día de granja actual exactamente como lo hace /harvest, mientras que las devoluciones HTD de la lista de ventas cuentan desde el 1 de abril junto a ingresos vs plan, con cada tarjeta imprimiendo su inicio y su fin?', 'HTD follows the farm today''s harvest year as the console does, so the dashboard and /harvest agree on every PPP figure.', 'HTD follows the fiscal April 1 clock on every row, so a first quarter farm day does not show a near empty PPP tile.', 'Yes: PPP follows the lot''s minted harvest year as /harvest shows it, returns follow the finance April clock from app_config dd_sales_htd_start_mmdd, and every HTD tile prints its start and end.', '04-01', 'ruled', '04-01', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_processed_lbs', 'processed_lbs', 'bizops.lbs_processed,harvest.trim_lb_per_dlh', 'dd_processed_lbs_buckets', 'Does "Lbs processed" mean the trim room''s weighed pounds alone, or trim, cryo and prepack side by side with trim as the headline and never summed?', '¿"Libras procesadas" significa solo las libras pesadas de la sala de recorte, o recorte, cryo y preempaque lado a lado con recorte como titular y nunca sumados?', 'Trim line only: the trim room''s weighed pounds are the one processed figure /harvest already proves, and summing lines counts a gram up to three times.', 'Every line: trim, cryo and prepack each by its own pane''s law, shown side by side so no bucket is ever added to another.', 'Show the three lines side by side with trim as the headline, each by its /harvest pane''s own law and never summed; a one item list behind the Admin PIN narrows it to trim alone.', 'trim,cryo,prepack', 'ruled', 'trim,cryo,prepack', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_shipped_interco', 'shipped_interco', 'bizops.lbs_shipped,bizops.shipments_count,bizops.moved_count,bizops.biomass_shipped_lb', 'dd_shipped_includes_interco', 'When a truck leaves a farm for the company''s own processing plant, does Shipments count it, or does Shipped mean left the company, with own licence moves shown beside it as Moved by destination site?', 'Cuando un camión sale de una granja hacia la planta de proceso de la propia empresa, ¿Envíos lo cuenta, o Enviado significa que salió de la empresa, con los movimientos entre licencias propias mostrados al lado como Movidos por sitio de destino?', 'Every truck that leaves a farm is a shipment, own plant or customer alike, as the mount page''s Shipped row counts today.', 'Shipped means left the company to a customer or partner; own licence moves are a separate Moved figure by destination site, computed once from the same set.', 'Shipped means left the company; own licence moves print beside it as Moved by destination site on the same card, pounds never add across the two, and dd_shipped_includes_interco can fold Moved into the count later without a code change.', '0', 'ruled', '0', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_active_window', 'active_window', 'sales.active_accounts_count,sales.lapsed_customers_count,sales.new_customers_count', 'dd_sales_active_days', 'Does "active account" mean an order in the trailing 30 days (the same clock as the Not Reordered list) or a longer window such as 90 days?', '¿"Cuenta activa" significa un pedido en los últimos 30 días (el mismo reloj que la lista de Sin recompra) o una ventana más larga como 90 días?', 'A 90 day window: the 31 to 90 day band is the at risk set the reorder conversation exists for, and 30 days alone hides it.', 'Thirty days on one shared key, so active plus not reordered equals the customer total and the two tiles never disagree.', 'Thirty days on one shared key, so active plus not reordered equals the customer total and the tile prints its window; raise the key later if a longer view is wanted and both tiles will follow it.', '30', 'ruled', '30', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_order_vs_invoice_week', 'order_vs_invoice_week', 'sales.units_sold,sales.avg_unit_price_usd,sales.revenue_weekly_usd,bizops.prepack_months_on_hand', 'dd_sales_week_basis', 'Does a sale belong to the week of its Zoho Order Date or to the week it shipped (today only the mount day of the status flip, later the Zoho invoice date)?', '¿Una venta pertenece a la semana de su fecha de pedido en Zoho o a la semana en que se envió (hoy solo el día de montaje del cambio de estado, después la fecha de factura de Zoho)?', 'The order week: order_date is a real date on every mounted row today and it is the basis the sales team plans against.', 'The shipped week: revenue is earned at shipment and a shipped keyed week closes its membership at the first mount after it, the only basis that can approach the QB month.', 'Order week now, badged by order week with shipped as of the mount, with the basis switchable to shipped week in app_config once the Zoho API supplies a real invoice or shipment date.', 'order', 'ruled', 'order', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_all_in_cost_scope', 'all_in_cost_scope', 'finance.all_in_cost_per_dry_lb,finance.all_in_cost_per_bud_lb', 'dd_all_in_addback_gls', 'Is 5420 Affiliated Purchases spend with a sister entity among PNN, PNS and SMI (adding it back would double count those pounds) or with an affiliate outside the three?', '¿5420 Compras afiliadas es gasto con una entidad hermana entre PNN, PNS y SMI (sumarlo de vuelta contaría esas libras dos veces) o con una afiliada fuera de las tres?', 'All in means the GRIPCasting landing scope as it stands: rent and affiliated purchases stay out and the figure is defined at every close.', 'All in adds rent (5570) and affiliated purchases (5420) back over weighed own lot grams, so the per pound cost carries every dollar the pounds consumed.', 'Ship with rent (5570) added back and 5420 kept out (dd_all_in_addback_gls = 5570), adding 5420 only if finance confirms the affiliate is outside PNN, PNS and SMI.', '5570', 'ruled', '5570', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_plan_source', 'plan_source', 'bizops.harvest_goal_pct,harvest.dry_lb_per_plant_vs_plan_pct,sales.units_sold,sales.avg_unit_price_usd,sales.revenue_weekly_usd,finance.revenue_vs_plan_usd,finance.forecast_landing_usd,finance.labor_hours,bizops.po_unplanned_pct', 'dd_plan_source', 'When finance resubmits the final GRIPCasting forecast, should revenue, volume, price and labor goals move to that submission, or stay frozen on one pinned submission?', 'Cuando finanzas vuelve a entregar el pronóstico final de GRIPCasting, ¿las metas de ingresos, volumen, precio y mano de obra deben moverse a esa entrega, o quedar congeladas en una entrega fijada?', 'One pinned submission: a goal that moves with every resubmit measures week 10 and week 30 against different plans with no stated reason.', 'The latest final submission: the board should read the plan finance stands behind today, with its close date on every tile.', 'Move with the latest final submission (dd_plan_source = latest_final), badge each tile with the submission''s close date, and pin a submission id only if you want a frozen annual baseline for a vs plan row.', 'latest_final', 'ruled', 'latest_final', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_projected_basis', 'projected_basis', 'harvest.ppp_dry_lb,harvest.btr_pct,culttech.projected_yield_lb', 'dd_projection_basis', 'For plants still standing, should projected PPP use the field estimate typed for that strain and farm, falling to the season''s own dry rate where none is typed, every cut lot at actual, the typed farm total under the line?', 'Para las plantas aún en pie, ¿el PPP proyectado debe usar la estimación de campo escrita para esa variedad y granja, cayendo a la tasa seca de la propia temporada donde no hay ninguna, con cada lote cortado a real y el total de granja escrito bajo la línea?', 'Actual to date applied to what remains: the console''s own projection, one law for every pane.', 'The plan values: the field estimate typed per strain and farm is the only yield plan in data and the projection should honour it where it exists.', 'Yes, and projected BTR stays the season weighted rate to date with the trim bogey shown beside it as the target, not inside it.', 'estimates', 'ruled', 'estimates', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z');

INSERT OR IGNORE INTO dd_kpi_questions (
  id, question_key, kpi_keys, config_key, question_en, question_es, position_a, position_b, recommendation, default_value, status, ruling, ruled_by, ruled_at, reason, created_at, updated_at
) VALUES
  ('ddq_moh', 'moh', 'bizops.prepack_months_on_hand', 'dd_moh_window_months', 'Months on hand (prepack stock per strain over trailing shipped velocity) or only the stock per strain already on /harvest?', '¿Meses de existencias (stock de preempaque por variedad sobre la velocidad de envío reciente) o solo el stock por variedad que ya está en /harvest?', 'Months on hand: stock over the trailing shipped velocity per strain is the bagging decision''s number.', 'Material on hand only: no bag count exists and sales run November to March, so a trailing window in October holds no selling month and the ratio misleads.', 'Months on hand over a trailing three month window of shipped orders by order_date, with the stock column shown beside it so the row stands when the window holds no sales.', '3', 'ruled', '3', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_product_life_cycle', 'product_life_cycle', 'bizops.batch_cycle_days', 'dd_product_life_cycle_mode', 'Days a harvest batch takes from entry to testing release (computable now), or a hand kept stage per sellable SKU (which first needs a SKU family list)?', '¿Días que tarda un lote de cosecha desde el ingreso hasta la liberación de pruebas (calculable hoy), o una etapa llevada a mano por SKU vendible (que primero necesita una lista de familias de SKU)?', 'Batch cycle days from harvest entry to testing release: computable today from the TAT status logs, no hand entry.', 'A hand kept lifecycle stage per sellable SKU: product means the sellable item everywhere the workbook uses the word, and the stage discipline is what the app lacks.', 'Batch cycle days from harvest entry to testing release, per strain with the open batch count, badged as definition v1 until a packed end is wired, with the SKU stage log deferred until a SKU family key exists.', 'batch_cycle', 'ruled', 'batch_cycle', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_contra_recompenses', 'contra_recompenses', 'culttech.contra_recompenses_usd', 'dd_contra_recompenses_mode', 'Is it the credits, discounts and in kind value exchanged with the four Continuum partners under the partner program, logged weekly by culttech per partner, or money owed to and by those partners, which finance already carries in the close upload?', '¿Son los créditos, descuentos y valor en especie intercambiados con los cuatro socios de Continuum bajo el programa de socios, registrados semanalmente por culttech por socio, o dinero que se debe a y por esos socios, que finanzas ya lleva en la carga de cierre?', 'The partner program''s recompense log: credits, discounts, service and in kind value per partner, typed by culttech as dated signed entries.', 'Money owed to and by the partners, which the close upload already carries on ordinary GLs, so nothing new is typed.', 'Treat it as the partner program''s recompense log: credits, discounts, service and in kind value received from (and, when it happens, given to) each of the four Continuum partners, typed by culttech as dated entries with a partner key, a signed amount and an optional project label, shown gross each way by week and never netted into any finance figure.', 'parked', 'parked', NULL, NULL, NULL, NULL, '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_retail_data_report', 'retail_data_report', 'finance.state_retail_sales_usd,sales.market_penetration_pct', 'dd_retail_report_source', 'The state''s CRA monthly figures read once a month for market context, or a report of the company''s own sell through at retail that someone compiles or pays for?', '¿Las cifras mensuales de la CRA del estado leídas una vez al mes como contexto de mercado, o un informe de la venta al detalle de los propios productos de la empresa que alguien compila o paga?', 'The state''s CRA monthly figures, typed once a month by finance, doubling as Market Penetration''s inputs.', 'A sell through report of the company''s own products at retail, which first needs a source nobody has named.', 'The CRA monthly figures, typed once a month by finance, with the licensee count and state dollars doubling as Market Penetration''s inputs; no sell through source exists to build on, and if one is ever named it becomes a separate sales row.', 'state_cra_monthly', 'ruled', 'state_cra_monthly', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_market_penetration', 'market_penetration', 'sales.market_penetration_pct', 'dd_market_penetration_basis', 'Which licence classes count as a door, for the numerator''s prefix list and the typed denominator: adult use retailers only, or retailers plus medical provisioning centers?', '¿Qué clases de licencia cuentan como puerta, para la lista de prefijos del numerador y el denominador escrito: solo minoristas de uso adulto, o minoristas más centros de provisión médica?', 'Door count share: distinct destination licences bought from in the trailing 90 days over the state''s active retailer count.', 'Share of state sales: doors do not measure depth, a door share can rise while volume falls.', 'Adult use retailer licences only, one per licensed location, taken from the CRA licensee list as of month end with the source and as of date typed beside the count, so a store holding both an adult use and a medical licence counts once.', 'doors', 'ruled', 'doors', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_btr_formula', 'btr_formula', 'harvest.btr_pct,culttech.strain_value_index,culttech.strain_scorecard', 'dd_btr_formula', 'Keep the trim room law exactly as /harvest shows it (BUD, SMALLS and SHAKE over all weight ran, WASTE in the denominator), or take WASTE out when strains are compared?', '¿Mantener la ley de la sala de recorte exactamente como la muestra /harvest (BUD, SMALLS y SHAKE sobre todo el peso procesado, con WASTE en el denominador), o sacar WASTE al comparar variedades?', 'The console pool: bud codes over all live trim grams with WASTE in, exactly as /harvest and the line packages footnote show it.', 'The puzzles ratio with WASTE out: a strain whose lots weighed more waste should not rank lower for a trim room fact.', 'Keep the trim room law with WASTE in, as /harvest and the line packages footnote already show it, and revisit only if WASTE grams on trim lots ever become material.', 'console_to_date', 'ruled', 'console_to_date', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_week_definition', 'week_definition', 'bizops.biomass_shipped_lb,bizops.inventory_by_stage_lb,bizops.metrc_harvest_variance_lb,bizops.harvest_goal_pct,bizops.compliance_issues_opened_count,bizops.lab_samples_submitted_count,bizops.ftq_pct,bizops.test_failures_by_mode_count,bizops.env_in_range_pct_by_space,bizops.prepack_months_on_hand,bizops.labor_forecast_hours,bizops.post_harvest_labor_hours,sales.units_sold,sales.avg_unit_price_usd,sales.revenue_weekly_usd,sales.lapsed_customers_count,sales.new_customers_count,sales.returns_count,sales.feedback_count,finance.cash_position_usd,finance.ar_ap_aging_usd,finance.labor_hours,finance.distillate_biomass_lb,farmops.equipment_downtime_h,farmops.safety_incidents_count,farmops.pm_overdue_count,farmops.applications_count,farmops.plants_planted_count,farmops.labor_scheduled_hours,culttech.rollouts_on_time_pct,culttech.projected_yield_lb,culttech.projects_in_progress_count,culttech.contra_recompenses_usd', 'dd_week_basis', 'Is the weekly bucket the ISO week of the farm day (Monday at the farm day start hour to the next Monday), with harvest week n shown as a label counted from a season start date pinned in app_config once the first cut lands?', '¿El balde semanal es la semana ISO del día de granja (lunes a la hora de inicio del día de granja hasta el lunes siguiente), con la semana de cosecha n mostrada como etiqueta contada desde una fecha de inicio de temporada fijada en app_config cuando cae el primer corte?', 'The ISO week of the farm day: a stable key every year, Monday at the farm day start hour to the next Monday.', 'The harvest week counted from the season''s first cut: directors say harvest week 3, and a goal keyed on week n is the same slot every plan year.', 'Yes: bucket and snapshot on the ISO week start date of the farm day, show harvest week n as a derived label inside the harvest year, and pin dd_season_start_date to the first live cut''s entry_date within the first harvest week rather than leaving the MIN(entry_date) bootstrap in place.', 'iso', 'ruled', 'iso', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z'),
  ('ddq_lot_date_law', 'lot_date_law', 'harvest.ppp_wet_lb,harvest.plants_harvested_count,harvest.wet_weight_lb', 'dd_lot_date_law', 'For yesterday''s PPP and plants harvested, does a lot belong to its Effective Date (the day its weighing started, PIN correctable, the date METRC carries as harvest start) or to the farm day it finished at the scale?', 'Para el PPP de ayer y las plantas cosechadas, ¿un lote pertenece a su fecha efectiva (el día en que empezó su pesaje, corregible con PIN, la fecha que METRC lleva como inicio de cosecha) o al día de granja en que terminó en la báscula?', 'The farm day the lot finished at the scale: a farm day is final at 06:00 the next morning, and the floor calls a lot finished after six today''s first batch.', 'The lot''s Effective Date: the day its weighing started, PIN correctable, the date METRC carries as harvest start.', 'Its Effective Date, with the farm day of the lot''s own created_at standing in for lots older than migration 0053, while wet weight by day keeps the /harvest console''s scale day law.', 'effective_date', 'ruled', 'effective_date', NULL, '2026-10-15T00:00:00.000Z', 'S0 ruling accepted by the owner 2026-10-15', '2026-10-15T00:00:00.000Z', '2026-10-15T00:00:00.000Z');

